-- Harder to audit, doesn't scale
GRANT SELECT ON TABLE finance.accounts_payable.invoices
  TO `alice@example.com`;
GRANT SELECT ON TABLE finance.accounts_payable.invoices
  TO `bob@example.com`;

-- Scales with the team, auditable in one place
GRANT SELECT ON TABLE finance.accounts_payable.invoices
  TO `data-analysts`;

-- Broader than necessary, if only one schema is needed
GRANT SELECT ON CATALOG finance TO `accounts-payable-team`;

-- Narrower, matches the actual need
GRANT SELECT ON SCHEMA finance.accounts_payable
  TO `accounts-payable-team`;

GRANT USE CATALOG ON CATALOG finance TO `data-analysts`;
GRANT USE SCHEMA ON SCHEMA finance.accounts_payable
  TO `data-analysts`;
GRANT SELECT ON TABLE finance.accounts_payable.invoices
  TO `data-analysts`;
